<!doctype html><html><head><meta charset="utf-8"><title>Receipt {{ $folio->folio_number }}</title><link rel="stylesheet" href="{{ asset('css/hms.css') }}"></head><body class="print-page"><div class="print-toolbar"><button onclick="window.print()" class="btn primary">Print receipt</button><button onclick="window.close()" class="btn">Close</button></div><article class="receipt"><h1>{{ $folio->property->name }}</h1><p>{{ $folio->property->address }}<br>{{ $folio->property->phone }}<br>TIN: {{ $folio->property->tin }}</p><hr><h2>PAYMENT RECEIPT</h2><div class="receipt-meta"><span>Folio</span><b>{{ $folio->folio_number }}</b><span>Guest</span><b>{{ $folio->guest->full_name }}</b><span>Reservation</span><b>{{ $folio->reservation?->reference }}</b><span>Date</span><b>{{ now()->format('d M Y h:i A') }}</b></div><hr>@foreach($folio->payments as $p)<div class="receipt-line"><div><b>{{ ucwords(str_replace('_',' ',$p->method)) }}</b><small>{{ $p->reference }} {{ $p->gateway_reference }}</small></div><b>UGX {{ number_format($p->amount) }}</b></div>@endforeach<hr><div class="receipt-total"><span>TOTAL PAID</span><b>UGX {{ number_format($folio->payments_total) }}</b></div><div class="receipt-total"><span>BALANCE</span><b>UGX {{ number_format($folio->balance) }}</b></div><p class="centre">Thank you for your stay.</p></article></body></html>
